def merge_weighted_intervals(intervals: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
    """
    Merge weighted intervals according to the specified rules.

    Args:
        intervals: List of tuples (start, end, weight) representing half-open intervals [start, end)

    Returns:
        List of merged tuples (start, end, total_weight) where adjacent segments with equal weights are coalesced.
    """
    if not intervals:
        return []
    valid_intervals = []
    for start, end, weight in intervals:
        if start < end and weight != 0:
            valid_intervals.append((start, end, weight))
    if not valid_intervals:
        return []
    points = set()
    for start, end, weight in valid_intervals:
        points.add(start)
        points.add(end)
    sorted_points = sorted(points)
    segments = []
    for i in range(len(sorted_points) - 1):
        a = sorted_points[i]
        b = sorted_points[i + 1]
        total_w = 0
        for start, end, weight in valid_intervals:
            if start <= a and end > a:
                total_w += weight
        if total_w != 0:
            segments.append((a, b, total_w))
    if not segments:
        return []
    coalesced = []
    current_start, current_end, current_weight = segments[0]
    for i in range(1, len(segments)):
        next_start, next_end, next_weight = segments[i]
        if current_end == next_start and current_weight == next_weight:
            current_end = next_end
        else:
            coalesced.append((current_start, current_end, current_weight))
            current_start, current_end, current_weight = (next_start, next_end, next_weight)
    coalesced.append((current_start, current_end, current_weight))
    return coalesced

def crc8_check(data: bytes) -> int:
    crc = 0
    for b in data:
        crc ^= b
        for _ in range(8):
            if crc & 128:
                crc = (crc << 1 ^ 7) & 255
            else:
                crc = crc << 1 & 255
    return crc

def range_sum_updates(nums: list[int], ops: list[tuple[str, int, int]]) -> list[int]:
    result = []
    arr = nums.copy()
    for op in ops:
        op_type = op[0]
        if op_type == 'add':
            idx = op[1]
            delta = op[2]
            if 0 <= idx < len(arr):
                arr[idx] += delta
        elif op_type == 'set':
            idx = op[1]
            val = op[2]
            if 0 <= idx < len(arr):
                arr[idx] = val
        elif op_type == 'sum':
            l = op[1]
            r = op[2]
            left = max(0, l)
            right = min(len(arr) - 1, r)
            if left > right:
                result.append(0)
            else:
                total = sum(arr[left:right + 1])
                result.append(total)
        else:
            pass
    return result

