def resolve_json_pointer(doc, pointer: str, default=None):
    """
    Resolve a JSON pointer (RFC 6901) in `doc`.

    Parameters:
    - doc: The data structure (dict, list, or primitive). Supports dict and list indexing.
    - pointer: A string representing the path, e.g., "/key/subkey" or "a/b/c".
    - default: Value to return if the pointer cannot be resolved.

    Returns:
        The value at the given pointer, or `default` if not found / invalid.
    """
    if pointer == '':
        return doc
    if not pointer.startswith('/'):
        return default
    tokens = pointer[1:].split('/')

    def unescape(token):
        token = token.replace('~1', '/')
        token = token.replace('~0', '~')
        return token
    current = doc
    for token in tokens:
        token = unescape(token)
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                return default
        elif isinstance(current, list):
            if token.isdigit() and token != '0':
                if token.startswith('0') and len(token) > 1:
                    return default
                idx = int(token)
                if 0 <= idx < len(current):
                    current = current[idx]
                else:
                    return default
            else:
                return default
        else:
            return default
    return current

