def shortest_path_at_most_k_edges(n: int, edges: list[tuple[int, int, int]], src: int, dst: int, max_edges: int) -> int:
    """
    Return minimum total path weight from src to dst using AT MOST max_edges edges.
    Directed weighted graph on `0 .. n - 1` where `(u, v, w)` has integer weight `w` (may be negative; no negative cycles).
    Return `0` if `src == dst` and no negative path needed; if `max_edges == 0`, return `0` if `src == dst` else `-1`. Return `-1` if unreachable within `max_edges` edges.
    """
    if max_edges < 0:
        return -1
    if max_edges == 0:
        return 0 if src == dst else -1
    adj = collections.defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))
    INF = float('inf')
    dp = [[INF] * n for _ in range(max_edges + 1)]
    dp[0][src] = 0
    for k in range(1, max_edges + 1):
        for v in range(n):
            if dp[k - 1][v] == INF:
                continue
            for u, weight in adj[v]:
                new_weight = dp[k - 1][v] + weight
                if new_weight < dp[k][u]:
                    dp[k][u] = new_weight
    min_w = INF
    for k in range(1, max_edges + 1):
        min_w = min(min_w, dp[k][dst])
    if min_w == INF:
        return -1
    else:
        return int(min_w)

def sliding_window_medians_x2(nums: list[int], k: int) -> list[int]:
    if k <= 0 or k > len(nums):
        return []
    result = []
    n = len(nums)
    for i in range(n - k + 1):
        window = nums[i:i + k]
        w_sorted = sorted(window)
        if k % 2 == 1:
            med = w_sorted[k // 2]
        else:
            med = (w_sorted[k // 2 - 1] + w_sorted[k // 2]) // 2
        if k % 2 == 1:
            val = w_sorted[k // 2]
            result.append(2 * val)
        else:
            val1 = w_sorted[k // 2 - 1]
            val2 = w_sorted[k // 2]
            result.append(val1 + val2)
    return result

def parameterize_sql_literals(query: str) -> tuple[str, list[str]]:
    """
    Scan query left-to-right:
    1. Preserve '--' single-line comments completely unchanged.
    2. Preserve double-quoted SQL identifiers "..." completely unchanged.
    3. Replace every single-quoted SQL string literal '...' with $1, $2, ... and append the unescaped value to params.
    """
    params: list[str] = []
    result: list[str] = []
    i = 0
    n = len(query)
    param_counter = 0
    while i < n:
        if i + 1 < n and query[i] == '-' and (query[i + 1] == '-'):
            end = query.find('\n', i)
            if end == -1:
                end = n
            result.append(query[i:end])
            i = end
            continue
        if query[i] == '"':
            j = i + 1
            while j < n:
                if query[j] == '"':
                    if j + 1 < n and query[j + 1] == '"':
                        j += 2
                    else:
                        j += 1
                        break
                else:
                    j += 1
            result.append(query[i:j])
            i = j
            continue
        if query[i] == "'":
            j = i + 1
            literal_chars: list[str] = []
            while j < n:
                if query[j] == "'":
                    if j + 1 < n and query[j + 1] == "'":
                        literal_chars.append("'")
                        j += 2
                    else:
                        j += 1
                        break
                else:
                    literal_chars.append(query[j])
                    j += 1
            param_counter += 1
            result.append(f'${param_counter}')
            params.append(''.join(literal_chars))
            i = j
            continue
        result.append(query[i])
        i += 1
    return (''.join(result), params)

def max_constrained_subseq_sum(nums: list[int], k: int) -> int:
    if not nums:
        raise ValueError('nums must not be empty')
    if k <= 0:
        raise ValueError('k must be positive')
    n = len(nums)
    dp = [0] * n
    from collections import deque
    dq = deque()
    dp[0] = nums[0]
    dq.append(0)
    for i in range(1, n):
        while dq and dq[0] < i - k:
            dq.popleft()
        if dq:
            best_prev = dp[dq[0]]
            if best_prev > 0:
                dp[i] = nums[i] + best_prev
            else:
                dp[i] = nums[i]
        else:
            dp[i] = nums[i]
        while dq and dp[dq[-1]] <= dp[i]:
            dq.pop()
        dq.append(i)
    return max(dp)

import hashlib

def consistent_hash_assign(nodes: list[str], vnodes: int, keys: list[str]) -> dict[str, str]:
    if not nodes or vnodes <= 0:
        return {}
    unique_nodes = list(dict.fromkeys(nodes))
    ring = []
    for node in unique_nodes:
        for v in range(vnodes):
            h = hashlib.sha256(f'{node}#{v}'.encode('utf-8')).digest()
            token = int.from_bytes(h[:8], 'big')
            ring.append((token, node))
    ring.sort(key=lambda x: (x[0], x[1]))
    result = {}
    for k in keys:
        kt = int.from_bytes(hashlib.sha256(k.encode('utf-8')).digest()[:8], 'big')
        n = len(ring)
        found = False
        for idx in range(n):
            t, node = ring[idx]
            if t >= kt:
                result[k] = node
                found = True
                break
        if not found:
            for idx in range(n):
                t, node = ring[idx]
                if t < kt:
                    result[k] = node
                    found = True
                    break
            if not found:
                result[k] = ring[-1][1]
    return result

