def conformal_threshold(scores: list[float], alpha: float) -> float:
    """
    Compute the exact finite-sample split-conformal calibration quantile.

    Parameters:
    - scores: list of float values
    - alpha: float in (0, 1)

    Returns:
        The k-th smallest element where k is determined by the formula.
    Raises ValueError if scores is empty.
    """
    if not scores:
        raise ValueError('scores must not be empty')
    n = len(scores)
    if alpha <= 0.0:
        return float('inf')
    if alpha >= 1.0:
        return float('-inf')
    k = math.ceil((n + 1) * (1.0 - alpha))
    if k <= 0:
        return float('-inf')
    if k > n:
        return float('inf')
    sorted_scores = sorted(scores)
    return float(sorted_scores[k - 1])

def route_benes_layer4(perm: list[int]) -> tuple[list[int], list[int]]:
    for is0 in [0, 1]:
        for is1 in [0, 1]:
            in_sw = [is0, is1]
            for os0 in [0, 1]:
                for os1 in [0, 1]:
                    out_sw = [os0, os1]
                    valid = True
                    for j in range(4):
                        i = perm[j]
                        s = i // 2
                        p = i % 2
                        mid_in = p ^ in_sw[s]
                        d = j // 2
                        q = j % 2
                        mid_out = q ^ out_sw[d]
                        if mid_in != mid_out:
                            valid = False
                            break
                    if valid:
                        return (in_sw, out_sw)
    raise ValueError('No valid switch configuration found')
